import html
def f(v):return 'Not available' if v is None else f'{v:.0f}'
def names(xs,n=10):return ', '.join(xs[:n]) or 'No named records returned'
def make(r):
 rows=''.join(f'<tr><td>{k}</td><td>{f(r["sa"].get(k))}</td><td>{f(r["sb"].get(k))}</td><td>{"Not available" if r["sa"].get(k) is None or r["sb"].get(k) is None else f"{r["sb"][k]-r["sa"][k]:+.0f}"}</td></tr>' for k in r['sa']);avail={k:v for k,v in r['sb'].items() if v is not None};bottom='No comparable dimensions returned.' if not avail else f"Strongest available destination dimension: {max(avail,key=avail.get)}. Weakest available: {min(avail,key=avail.get)}."
 hz=''.join('<div class=card><h3>'+h+'</h3><ul>'+''.join(f'<li><b>{a}:</b> {html.escape(b)}</li>' for a,b in x)+'</ul></div>' for h,x in r['hz'].items());e=r['eb'];food='Unavailable' if not e['food'] else f"{e['food']['count']} food businesses returned; {e['food']['rated_4_5']} had numeric hygiene ratings of 4 or 5.";terrain='Unavailable' if not e['terrain'] else f"Centre elevation {e['terrain']['centre']:.0f} m; sampled local range {e['terrain']['range']:.0f} m."
 return f'''<!doctype html><meta charset=utf-8><style>body{{font-family:Segoe UI,Arial;max-width:1050px;margin:auto;color:#17332d}}header{{background:linear-gradient(120deg,#123f52,#0f766e);color:white;padding:38px}}section{{padding:24px;border-bottom:1px solid #ddd}}h2{{color:#0f766e}}table{{width:100%;border-collapse:collapse}}th,td{{padding:9px;border-bottom:1px solid #ddd;text-align:left}}th{{background:#eff8f5}}.grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}}.card{{background:#f6faf8;padding:15px}}</style><header><h1>Location Lifestyle AI v1.2</h1><p>{html.escape(r['a']['label'])} → {html.escape(r['b']['label'])}</p></header><section><h2>Bottom line</h2><p>{html.escape(bottom)}</p></section><section><h2>Lifestyle fingerprint</h2><table><tr><th>Dimension</th><th>Current</th><th>Destination</th><th>Difference</th></tr>{rows}</table></section><section><h2>Next chapter</h2><div class=grid>{hz}</div></section><section><h2>Named destination evidence</h2><h3>Active life</h3><p>{html.escape(names(e['osm']['Active life']))}</p><h3>Culture and learning</h3><p>{html.escape(names(e['osm']['Learning & culture']))}</p><h3>Nearby Wikipedia places</h3><p>{html.escape(names(e['wiki']))}</p><h3>Historic England records</h3><p>{html.escape(names([x['name'] for x in e['heritage']]))}</p><h3>Family</h3><p>{html.escape(names(e['osm']['Family visits']))}</p><h3>Community</h3><p>{html.escape(names(e['osm']['Community']))}</p><h3>Outdoors</h3><p>{html.escape(names(e['osm']['Outdoors']))}</p><h3>Water life</h3><p>{html.escape(names(e['osm']['Water life']))}</p></section><section><h2>Extra evidence</h2><p><b>Food footprint:</b> {food}</p><p><b>Terrain:</b> {terrain}</p><p><b>OpenBenches:</b> {'Unavailable' if e['benches'] is None else str(e['benches'])+' nearby contributed records'}.</p><p><b>Police.uk:</b> {'Unavailable' if e['crime'] is None else str(e['crime'])+' recent records returned'}.</p></section><section><h2>Source health</h2><ul>{''.join(f'<li>{"Available" if x["ok"] else "Unavailable"}: <b>{x["source"]}</b> – {x["detail"]}</li>' for x in r['statuses'])}</ul></section>'''
